static f32 SquirmDraw(const Rfloat &r)
{
	/* Rfloat::operator float 0x25aba0 (inline here) */
	return r.m_range == 0.0f ? r.m_min : r.m_min + r.m_range * ((f32)rand() * 4.656613e-10f);
}

